119	
120	    public LocalDate getRegistrationDate() {
121	        return this.registrationDate;
122	    }
123	
124	    public void setRegistrationDate(LocalDate registrationDate) {
125	        this.registrationDate = registrationDate;
126	    }
127	
128	    public String getCustomerCode() {
129	        return this.customerCode;
130	    }
131	
132	    public void setCustomerCode(String customerCode) {
133	        this.customerCode = customerCode;
134	    }
135	
136	    public String getHouseholdId() {
137	        return this.householdId;
138	    }
139	
140	    public void setHouseholdId(String householdId) {
141	        this.householdId = householdId;
142	    }
143	
144	    public Integer getNamesakeCount() {
145	        return this.namesakeCount;
146	    }
147	
148	    public void setNamesakeCount(Integer namesakeCount) {
149	        this.namesakeCount = namesakeCount;
150	    }
151	
152	    public String getMembershipNumber() {
153	        return this.membershipNumber;
154	    }
155	
156	    public void setMembershipNumber(String membershipNumber) {
157	        this.membershipNumber = membershipNumber;
158	    }
159	
160	    public Boolean getBulkSignupWarning() {
161	        return this.bulkSignupWarning;
162	    }
163	
164	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
165	        this.bulkSignupWarning = bulkSignupWarning;
166	    }
167	
168	    protected Set<Pet> getPetsInternal() {
169	        if (this.pets == null) {
170	            this.pets = new HashSet<>();
171	        }
172	        return this.pets;
173	    }
174	
175	    protected void setPetsInternal(Set<Pet> pets) {
176	        this.pets = pets;
177	    }
178	
179	    public List<Pet> getPets() {
180	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
181	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
182	        return Collections.unmodifiableList(sortedPets);
183	    }
184	
185	    public void setPets(List<Pet> pets) {
186	        this.pets = new HashSet<>(pets);
187	    }
188	
189	    public void addPet(Pet pet) {
190	        getPetsInternal().add(pet);
191	        pet.setOwner(this);
192	    }
193	
194	    /**
195	     * Return the Pet with the given name, or null if none found for this Owner.
196	     *
197	     * @param name to test
198	     * @return true if pet name is already in use
199	     */
200	    public Pet getPet(String name) {
201	        return getPet(name, false);
