17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.Collection;
24	import java.util.List;
25	import java.util.Locale;
26	import java.util.regex.Pattern;
27	
28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
41	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
42	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Minimal syntactic check for an email address: a non-empty local part, a single
68	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
73	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
74	
75	    /** Dedicated audit logger; emits an audit line on successful owner create. */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    private final TelephoneNormalizer telephoneNormalizer;
87	
88	    private final AddressNormalizer addressNormalizer;
89	
90	    private final CityRegionResolver cityRegionResolver;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper,
96	                                 TelephoneNormalizer telephoneNormalizer,
97	                                 AddressNormalizer addressNormalizer,
98	                                 CityRegionResolver cityRegionResolver) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	        this.telephoneNormalizer = telephoneNormalizer;
104	        this.addressNormalizer = addressNormalizer;
105	        this.cityRegionResolver = cityRegionResolver;
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
111	        Collection<Owner> owners;
112	        if (lastName != null) {
113	            owners = this.clinicService.findOwnerByLastName(lastName);
114	        } else {
115	            owners = this.clinicService.findAllOwners();
116	        }
117	        if (owners.isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
126	        Owner owner = this.clinicService.findOwnerById(ownerId);
127	        if (owner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
136	        HttpHeaders headers = new HttpHeaders();
137	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
138	        if (owner.getRegistrationDate() == null) {
139	            owner.setRegistrationDate(LocalDate.now());
140	        }
141	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
142	        LocalDate registrationDate = owner.getRegistrationDate();
143	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
144	            .map(Owner::getRegistrationDate)
145	            .filter(registrationDate::equals)
146	            .count();
147	        if (ownersCreatedThatDay >= 100) {
148	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
149	        }
150	        String address = addressNormalizer.normalize(owner.getAddress());
151	        if (address.isBlank()) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        owner.setAddress(address);
155	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
156	        if (telephone == null) {
157	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
158	        }
159	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
160	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
161	        }
162	        owner.setTelephone(telephone);
163	        String email = owner.getEmail();
164	        if (email != null) {
165	            email = email.trim();
166	            if (!EMAIL_PATTERN.matcher(email).matches()) {
167	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
168	            }
169	            owner.setEmail(email.toLowerCase(Locale.ROOT));
170	        }
171	        // A postcode is optional, but when supplied it must be four digits and valid for the
172	        // owner's city per the fixed region table; a city with no known region accepts any
173	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
174	        String postcode = owner.getPostcode();
175	        if (postcode != null) {
176	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
177	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
178	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
179	            }
180	        }
181	        // The owner's telephone and email are now in their canonical, stored form.
182	        // Establish the household id before the duplicate check so the candidate's whole
183	        // identity key can be compared against the existing owners': only an owner that
184	        // deliberately shares an existing household (same normalized last name and address)
185	        // is assigned that household's shared id; a plain new owner has no household id, so
186	        // its identity key is decided by telephone and email alone.
187	        String lastNameKey = normalizeIdentity(owner.getLastName());
188	        String addressKey = addressNormalizer.normalize(owner.getAddress());
189	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
190	                && householdExists(lastNameKey, addressKey)) {
191	            owner.setHouseholdId(householdId(lastNameKey, addressKey));
192	        }
193	        if (isDuplicateOwner(owner)) {
194	            return new ResponseEntity<>(HttpStatus.CONFLICT);
195	        }
196	        String cityKey = normalizeIdentity(owner.getCity());
197	        long ownersInCity = this.clinicService.findAllOwners().stream()
198	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
199	            .count();
200	        if (ownersInCity >= 50) {
201	            return new ResponseEntity<>(HttpStatus.CONFLICT);
202	        }
203	        owner.setCustomerCode(customerCode(owner));
204	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
205	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
206	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
207	            .count();
208	        owner.setNamesakeCount(namesakeCount);
209	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
210	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
211	        this.clinicService.saveOwner(owner);
212	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
213	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
214	            ownerMapper.membershipLevel(owner));
215	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
216	        headers.setLocation(UriComponentsBuilder.newInstance()
217	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
218	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
219	    }
220	
221	    /**
222	     * Whether {@code candidate} collides with an already-registered owner under the single
223	     * identity rule enforced on create. This is the one point at which a new owner is
224	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
225	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
226	     * email (or an empty string when absent) and the householdId joined by '|'. The
227	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
228	     * the telephone is part of the key, two members of the same household (same householdId)
229	     * with different telephones have different identityKeys and are both allowed.
230	     *
231	     * <p>The candidate arrives with its telephone and email already normalized and its
232	     * household id already derived, and each existing owner is stored in the same canonical
233	     * form, so an identityKey match means the two owners are genuinely the same identity.
234	     *
235	     * @param candidate the fully-normalized owner about to be created
236	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
237	     */
238	    private boolean isDuplicateOwner(Owner candidate) {
239	        String identityKey = OwnerMapper.identityKey(candidate);
